package com.trampolim.api.career;
import java.util.*;import java.time.*;import java.security.SecureRandom;
import com.trampolim.api.radar.*;import static com.trampolim.api.radar.RadarModel.*;
import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@RestController public class CareerPassportLinkController {
 private final JdbcTemplate db;private final SkillCatalog users;private final RadarBridge bridge;
 public CareerPassportLinkController(@Qualifier("jdbcTemplate")JdbcTemplate db,SkillCatalog users,RadarBridge bridge){this.db=db;this.users=users;this.bridge=bridge;}
 public record Consent(boolean consent){}public record Redeem(String token,UUID credentialId){}public record Check(UUID credentialId){}
 @PostMapping("/api/career/challenges/submissions/{receipt}/passport-link")@Transactional("oportunidadesTransactionManager")public Map<String,Object> issue(@AuthenticationPrincipal String email,@PathVariable UUID receipt,@RequestBody Consent p){long uid=users.user(email);if(p==null||!p.consent())bad("Confirme o compartilhamento do resultado com sua conta independente do Capacita.");db.queryForObject("SELECT id FROM app_users WHERE id=? FOR UPDATE",Long.class,uid);if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM career_challenge_submissions WHERE user_id=? AND receipt_id=? AND withdrawn_at IS NULL)",Boolean.class,uid,receipt)))throw new ResponseStatusException(HttpStatus.NOT_FOUND);if(db.queryForObject("SELECT count(*) FROM career_passport_links WHERE user_id=? AND consent_at>CURRENT_TIMESTAMP-INTERVAL '1 hour'",Integer.class,uid)>=10)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS);var evidence=bridge.post("/integrations/career/challenges/evidence",new CompanyCareerService.Receipt(1,receipt));if(!evidence.path("status").asText().equals("ACTIVE"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Use um resultado aprovado e válido.");byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);db.update("INSERT INTO career_passport_links(token_hash,user_id,receipt_id,expires_at) VALUES (?,?,?,CURRENT_TIMESTAMP+INTERVAL '15 minutes')",RadarBridge.hash(token),uid,receipt);return Map.of("token",token,"expiresInMinutes",15,"notice","Cole este código somente na sua conta do Capacita. Não compartilha senha, sessão, resposta ou contato.");}
 @DeleteMapping("/api/career/challenges/passport-links/{credential}")public void revoke(@AuthenticationPrincipal String email,@PathVariable UUID credential){if(db.update("UPDATE career_passport_links SET revoked_at=COALESCE(revoked_at,CURRENT_TIMESTAMP) WHERE user_id=? AND credential_id=?",users.user(email),credential)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);}
 @PostMapping("/api/integrations/career/challenges/passport/redeem")@Transactional("oportunidadesTransactionManager")public Map<String,Object> redeem(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody Redeem p){bridge.authorize(key);if(p==null||p.credentialId()==null||p.token()==null||!p.token().matches("[A-Za-z0-9_-]{43}"))bad("Código inválido.");var rows=db.queryForList("SELECT l.*,s.withdrawn_at FROM career_passport_links l JOIN career_challenge_submissions s ON s.receipt_id=l.receipt_id WHERE l.token_hash=? FOR UPDATE OF l",RadarBridge.hash(p.token()));if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var r=rows.getFirst();if(r.get("revoked_at")!=null||r.get("withdrawn_at")!=null||r.get("credential_id")==null&&!((java.sql.Timestamp)r.get("expires_at")).toInstant().isAfter(Instant.now())||r.get("credential_id")!=null&&!r.get("credential_id").equals(p.credentialId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Código indisponível, expirado ou já vinculado.");var evidence=fetch(r);db.update("UPDATE career_passport_links SET credential_id=? WHERE token_hash=?",p.credentialId(),RadarBridge.hash(p.token()));return evidence;}
 @PostMapping("/api/integrations/career/challenges/passport/check")public Map<String,Object> check(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody Check p){bridge.authorize(key);if(p==null||p.credentialId()==null)bad("Credencial inválida.");var rows=db.queryForList("SELECT l.receipt_id FROM career_passport_links l JOIN career_challenge_submissions s ON s.receipt_id=l.receipt_id JOIN app_users u ON u.id=l.user_id WHERE l.credential_id=? AND l.revoked_at IS NULL AND s.withdrawn_at IS NULL AND u.email_verified=TRUE",p.credentialId());if(rows.isEmpty())return Map.of("status","INVALID","formalCertificate",false);return fetch(rows.getFirst());}
 private Map<String,Object> fetch(Map<String,Object> row){var evidence=bridge.post("/integrations/career/challenges/evidence",new CompanyCareerService.Receipt(1,(UUID)row.get("receipt_id")));if(!evidence.path("status").asText().equals("ACTIVE"))throw new ResponseStatusException(HttpStatus.CONFLICT,"O resultado não permanece válido.");return bridge.convert(evidence,Map.class);}
}
